import { useState } from "react";

function App() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);

  const handleSearch = async () => {
    const res = await fetch(`http://localhost:8000/search/?query=${query}`);
    const data = await res.json();
    setResults(data.results || []);
  };

  return (
    <div className="App">
      <div className="search-bar-container"Hello World>
        <h1>Product Search</h1>
        <input
          type="text"
          placeholder="Enter a Product or Service"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        <button onClick={handleSearch}>Search</button>
      </div>

      <div className="search-results-container">
        <ul>
          {results.map((item, idx) => (
            <li key={idx}>
              <strong>{item.product_item_name}</strong> - {item.business_name}
              <br />
              <em>{item.product_description}</em>
              <br />
              ${item.price}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

export default App;
